  if (target.family === 'cart') return `<main class="page-content cart-page" data-node-id="main"><div class="breadcrumbs">خانه <span>←</span> سبد خرید</div>${sectionHead(title,'NOVA / YOUR BAG')}<div class="cart-layout"><section class="cart-items" data-node-id="cart-items">${frame.state==='empty'?'<div class="empty-state large">سبد خرید شما هنوز خالی است.<a class="button primary">دیدن محصولات</a></div>':`${frame.state==='error'?'<div class="inline-alert">قیمت یا موجودی یکی از کالاها تغییر کرده؛ پیش از ادامه بررسی کنید.</div>':''}${[0,1].map(i=>`<article class="cart-row"><img src="${dataUrl(i?'nova-product-soft-trousers.webp':'nova-product-linen-overshirt.webp')}" alt="محصول نمونه"><div><b>${i?'شلوار کتان نرم':'پیراهن لینن بافت‌دار'}</b><small>زیتونی روشن · سایز M</small><div class="quantity"><button>−</button><span>۱</span><button>＋</button></div></div><div class="cart-price"><bdi>۲٬۴۸۰٬۰۰۰ تومان</bdi><a>حذف</a></div></article>`).join('')}`}<a class="text-link">ادامه‌ی خرید ←</a></section><aside class="order-summary" data-node-id="summary"><h2>خلاصه‌ی سفارش</h2><div><span>جمع کالاها</span><b>۴٬۳۷۰٬۰۰۰ تومان</b></div><div><span>هزینه‌ی ارسال</span><b>در مرحله‌ی بعد</b></div><div class="summary-total"><span>مبلغ قابل پرداخت</span><b>۴٬۳۷۰٬۰۰۰ تومان</b></div><label class="promo-field">کد تخفیف <input placeholder="کد را وارد کنید"></label><button class="button primary" data-node-id="primary-action">ادامه به تسویه‌حساب</button><small>مبلغ نمونه؛ محاسبه‌ی واقعی از API می‌آید.</small></aside></div></main>`;

