  if (target.family === 'status') return `<main class="status-stage" data-node-id="main"><section class="status-card" data-node-id="status-panel"><span class="status-mark ${frame.state}">${frame.state==='success'?'✓':frame.state==='error'?'!':'…'}</span><span class="eyebrow">NOVA / ${target.id.toUpperCase()}</span><h1>${title}</h1><p>${frame.note?normalizeText(frame.note):'وضعیت به‌روز سفارش را بررسی کنید یا یکی از راه‌های ادامه را انتخاب کنید.'}</p>${target.id==='web-not-found'?'<div class="recovery-links"><a>بازگشت به خانه</a><a>دیدن محصولات</a></div>':`<div class="status-meta"><span>شناسه‌ی نمایشی</span><bdi>NV-1405-08-214</bdi><span>آخرین به‌روزرسانی</span><bdi>۱۴:۳۸</bdi></div><div class="recovery-links"><button class="button primary" data-node-id="primary-action">${frame.state==='error'?'تلاش دوباره':target.id==='web-system-states'?'بازگشت به خانه':'دیدن سفارش'}</button><a>تماس با پشتیبانی</a></div>`}<small>داده‌ها و شناسه‌ها نمونه هستند.</small></section></main>`;

