  const sceneGraph={schemaVersion:'1.0.0',coordinateSystem:'CSS pixels, origin top-left; physical X increases right in RTL',nodes:sceneNodes,frames:framesSpec.map((frame)=>({frameId:frame.id,rootIds:frame.measurements.filter((node)=>node.viewportId==='desktop'&&['header','main'].includes(node.id)).map((node)=>`${frame.id}-${node.viewportId}-${node.id}`)}))};
  const coverage={version:'1.0.0',status:selectedTargets.length===targets.length?'GENERATED':'IN_PROGRESS',targets:targets.map((target)=>({targetId:target.id,app:target.app,routeCount:target.routes.length,frames:target.frames.map((frame)=>({frameId:`${target.id}-${frame.id}`,route:frame.route,state:frame.state,artifacts:selectedTargets.some((x)=>x.id===target.id)?['desktop-clean','mobile-clean','page-board']:'',status:selectedTargets.some((x)=>x.id===target.id)?'GENERATED':'REQUIRED'})),viewports:['1440x900','390x844',...(target.tablet?['768x1024']:[])],artifacts:selectedTargets.some((x)=>x.id===target.id)?{board:'GENERATED',desktop:'GENERATED',mobile:'GENERATED'}:{board:'REQUIRED',desktop:'REQUIRED',mobile:'REQUIRED'}}))};
  const errors=validateSemantics(spec,sceneGraph,coverage);
  spec.qa.checks.push({id:'semantic-integrity',status:errors.length?'FAIL':'PASS',method:'Deterministic target/frame/node reference checks',evidence:errors.length?errors.join('; '):`Unique target IDs, frame ownership, scene node references and ${coverage.targets.length} coverage rows verified.`});
  if(errors.length)spec.qa.status='FAIL';
  asFile(path.join(outputRoot,'design-spec.json'),spec);
  asFile(path.join(outputRoot,'scene-graph.json'),sceneGraph);
  asFile(path.join(outputRoot,'source-index.json'),{sources:sourceIndex,revision:spec.sourceRevision,indexing:'Graph index used for discovery; source files read directly where index freshness metadata changed.'});
